-- Operations 维护 Vault 数据类型与手动加解密：Platform 注册数据（2026-10-14 阶段 3 评审稿，待执行文件）
-- 目标库：Platform Support 业务库；手工执行需单独授权，应用启动不会执行。
-- 字符集：用 mysql --default-character-set=utf8mb4 执行；客户端默认 latin1 会把中文（注释、名称、理由）写成乱码。
-- 174 行 INSERT；0 UPDATE / DELETE；不新增 Gateway Target，不改表结构。
-- 新路由与菜单资源为 DISABLED，PLATFORM_ADMIN 授权为 REVOKED；激活另行处理。
-- 执行前：把 @vlt_operator 设为已批准的真实 Operations 账号 ID；在同一交互连接中执行，不使用 --force。
-- 本文件不含 COMMIT：核对插入行数与 ID 后手工 COMMIT，任何不符则 ROLLBACK。
SET @vlt_time=UTC_TIMESTAMP(6);
SET @vlt_target=(SELECT target_id FROM t_gateway_target WHERE target_service_code='operations-console-bff' AND channel='OPERATIONS' AND status='ACTIVE');
SET @vlt_admin=(SELECT role_id FROM t_role WHERE role_code='PLATFORM_ADMIN' AND scope_key='PLATFORM' AND system_role=1 AND status='ACTIVE');
SELECT @vlt_operator operator_id,@vlt_target target_id,@vlt_admin admin_role_id;
-- 上面三个值任一为空时停止，不进入事务。
START TRANSACTION;








-- 预期：6 权限、6 角色授权（REVOKED）、11 菜单/按钮、13 路由、42 请求头、18 查询参数、78 限流规则；核对后 COMMIT。
